import { test, expect } from '@playwright/test';

test.describe('Mobile Navigation Collapse to Hamburger Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/mobile-page');
  });

  test('should collapse navigation into hamburger menu on mobile viewport', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 862 });

    // Verify navigation links are visible before collapse
    const navLinks = page.getByRole('navigation').getByText('Home');
    await expect(navLinks).toBeVisible();

    // Verify hamburger menu button is visible
    const hamburgerButton = page.getByRole('button', { name: /menu/i });
    await expect(hamburgerButton).toBeVisible();

    // Click hamburger menu button
    await hamburgerButton.click();

    // Verify menu overlay appears
    const menuOverlay = page.locator('[data-testid="menu-overlay"]');
    await expect(menuOverlay).toBeVisible();

    // Verify menu items are now visible in overlay
    const menuItems = page.getByRole('menuitem');
    await expect(menuItems).toHaveCount(5);

    // Verify menu items are accessible
    const homeMenuItem = page.getByRole('menuitem', { name: /home/i });
    await expect(homeMenuItem).toBeVisible();

    // Verify menu overlay has correct styling
    const overlayStyle = await menuOverlay.evaluate((el) => window.getComputedStyle(el).display);
    expect(overlayStyle).toBe('block');
  });

  test('should expand navigation from hamburger menu and close on click', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 860 });

    // Click hamburger menu button to open menu
    const hamburgerButton = page.getByRole('button', { name: /menu/i });
    await hamburgerButton.click();

    // Verify menu overlay is visible
    const menuOverlay = page.locator('[data-testid="menu-overlay"]');
    await expect(menuOverlay).toBeVisible();

    // Click home menu item
    const homeMenuItem = page.getByRole('menuitem', { name: /home/i });
    await homeMenuItem.click();

    // Verify menu overlay closes
    await expect(menuOverlay).not.toBeVisible();

    // Verify user is navigated to home page
    await expect(page).toHaveURL(/.*\/home/);

    // Click hamburger menu button again to reopen menu
    await hamburgerButton.click();
    await expect(menuOverlay).toBeVisible();

    // Click settings menu item
    const settingsMenuItem = page.getByRole('menuitem', { name: /settings/i });
    await settingsMenuItem.click();

    // Verify menu overlay closes after navigation
    await expect(menuOverlay).not.toBeVisible();
  });
});
